using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class DemoEnemySetup
{
 const string Folder="Assets/Prefabs/Encounters/";
 public static void Run(){try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);AssetDatabase.Refresh();
 foreach(bool fly in new[]{true,false}){var g=Create(fly);PrefabUtility.SaveAsPrefabAsset(g,Folder+(fly?"FrostMossfly":"EchoHornhead")+".prefab");Object.DestroyImmediate(g);}
 Add("08_SporePass_Painted",true);Add("12_RiftVault_Painted",false);
 AssetDatabase.SaveAssets();File.WriteAllText("new-enemies-setup.txt","Frost Mossfly added to Spore Pass; Echo Hornhead added to Rift Vault. Existing encounters preserved.\n");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static Sprite[] Frames(string p)=>AssetDatabase.LoadAllAssetsAtPath("Assets/Hollow/enemies/"+p+".png").OfType<Sprite>().OrderBy(s=>int.Parse(s.name.Split('_').Last())).ToArray();
 static GameObject Create(bool fly){var anchor=new GameObject(fly?"Frost Mossfly":"Echo Hornhead");var g=new GameObject("Body");g.transform.SetParent(anchor.transform,false);g.layer=10;var rb=g.AddComponent<Rigidbody2D>();rb.gravityScale=fly?0:4;rb.constraints=RigidbodyConstraints2D.FreezeRotation;rb.collisionDetectionMode=CollisionDetectionMode2D.Continuous;rb.interpolation=RigidbodyInterpolation2D.Interpolate;var c=g.AddComponent<BoxCollider2D>();c.size=new Vector2(.8f,1);c.sharedMaterial=AssetDatabase.LoadAssetAtPath<PhysicsMaterial2D>("Assets/ZeroFriction.physicsMaterial2D");var sr=g.AddComponent<SpriteRenderer>();sr.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/Painted/PaintedSprites.mat");sr.sortingOrder=30;var h=g.AddComponent<EnemyHealth>();h.maxHealth=fly?2:4;var ai=g.AddComponent<HollowEnemy>();ai.flying=fly;ai.visual=sr;ai.idle=Frames(fly?"mossfly/Fly":"husk_hornhead/Idle");ai.move=Frames(fly?"mossfly/Fly":"husk_hornhead/Walk");ai.charge=Frames(fly?"mossfly/Fly":"husk_hornhead/Charge");sr.sprite=ai.idle[0];var warning=new GameObject("Attack warning");warning.transform.SetParent(g.transform,false);warning.transform.localPosition=Vector3.up*1.1f;warning.transform.localScale=Vector3.one*.4f;ai.warning=warning.AddComponent<SpriteRenderer>();ai.warning.sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/Demo/Warning.png");ai.warning.sharedMaterial=sr.sharedMaterial;ai.warning.sortingOrder=35;ai.warning.enabled=false;var actor=anchor.AddComponent<DimensionActor>();actor.dimension=fly?0:1;actor.content=g;return anchor;}
 static void Add(string name,bool fly){string path=Folder+name+".prefab";var root=PrefabUtility.LoadPrefabContents(path);string label=fly?"Frost Mossfly":"Echo Hornhead";var existing=root.transform.Find(label);if(existing!=null)Object.DestroyImmediate(existing.gameObject);Physics2D.SyncTransforms();var physics=root.scene.GetPhysicsScene2D();float width=root.transform.Find("EndPosition").localPosition.x;Vector3 pos=Vector3.zero;bool found=false;
 for(float x=width*.5f;x<width-4;x+=2){var hit=physics.Raycast(new Vector2(x,30),Vector2.down,50,1<<8);if(hit.collider==null)continue;var p=new Vector3(x,hit.point.y+(fly?2.7f:.52f));if(root.GetComponentsInChildren<EnemyHealth>(true).Any(e=>Vector2.Distance(e.transform.position,p)<4))continue;if(!fly){var l=physics.Raycast(new Vector2(x-2,hit.point.y+1),Vector2.down,3,1<<8);var r=physics.Raycast(new Vector2(x+2,hit.point.y+1),Vector2.down,3,1<<8);if(l.collider==null||r.collider==null||Mathf.Abs(l.point.y-r.point.y)>.2f)continue;}pos=p;found=true;break;}
 if(!found)throw new Exception("No clear spawn in "+name);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+(fly?"FrostMossfly":"EchoHornhead")+".prefab");var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,root.transform);g.name=label;g.transform.localPosition=pos;PrefabUtility.SaveAsPrefabAsset(root,path);PrefabUtility.UnloadPrefabContents(root);}
}
